/**
 * NewsStudio — Unified Audio Tag Lexicon & Model Transpiler
 * 
 * Defines a single, standardized set of emotive/audio tags generated by LLMs:
 *   [laugh], [chuckle], [sigh], [gasp], [whisper], [pause], [cough], [throat_clear]
 * 
 * And transpiles them into the exact native syntax expected by each target TTS model:
 * - Orpheus 3B: <laugh>, <chuckle>, <sigh>, <gasp>, <whisper>, <cough>
 * - ChatTTS: [laugh], [sigh], [break_4]
 * - Suno Bark: [laughs], [sighs], [gasps], [clears throat], ...
 * - F5-TTS / CosyVoice 3: Natural cadence, ellipses (...), em-dashes (—)
 * - Piper / Kokoro / MeloTTS / XTTS / OmniVoice: Clean punctuation, stripped tags
 */

export const STANDARD_AUDIO_TAGS = [
  "[laugh]",
  "[chuckle]",
  "[sigh]",
  "[gasp]",
  "[whisper]",
  "[pause]",
  "[cough]",
  "[throat_clear]"
] as const;

export type StandardAudioTag = typeof STANDARD_AUDIO_TAGS[number];

/**
 * Transpiles text containing generic standard audio tags into model-specific syntax.
 */
export function transpileAudioTagsForModel(text: string, targetEngine: string = "piper"): string {
  if (!text || typeof text !== "string") return "";

  const engine = targetEngine.toLowerCase().trim();

  // 1. Orpheus 3B Engine
  if (engine.includes("orpheus")) {
    return text
      .replace(/\[laugh\]/gi, "<laugh>")
      .replace(/\[chuckle\]/gi, "<chuckle>")
      .replace(/\[sigh\]/gi, "<sigh>")
      .replace(/\[gasp\]/gi, "<gasp>")
      .replace(/\[whisper\]/gi, "<whisper>")
      .replace(/\[pause\]/gi, "... ")
      .replace(/\[(cough|throat_clear)\]/gi, "<cough>")
      // Strip any other unknown brackets but keep XML tags
      .replace(/\[[^\]]+\]/g, "")
      .replace(/\s+/g, " ")
      .trim();
  }

  // 2. ChatTTS Engine
  if (engine.includes("chattts")) {
    return text
      .replace(/\[(laugh|chuckle)\]/gi, "[laugh]")
      .replace(/\[sigh\]/gi, "[sigh]")
      .replace(/\[(gasp|pause)\]/gi, "[break_4]")
      .replace(/\[(whisper|cough|throat_clear)\]/gi, "")
      .replace(/<[^>]+>/g, "")
      .replace(/\s+/g, " ")
      .trim();
  }

  // 3. Suno Bark Engine
  if (engine.includes("bark")) {
    return text
      .replace(/\[(laugh|chuckle)\]/gi, "[laughs]")
      .replace(/\[sigh\]/gi, "[sighs]")
      .replace(/\[gasp\]/gi, "[gasps]")
      .replace(/\[(cough|throat_clear)\]/gi, "[clears throat]")
      .replace(/\[pause\]/gi, "... ")
      .replace(/\[whisper\]/gi, "")
      .replace(/<[^>]+>/g, "")
      .replace(/\s+/g, " ")
      .trim();
  }

  // 4. F5-TTS (Flow Matching) Engine
  if (engine.includes("f5") || engine.includes("f5_tts")) {
    return text
      .replace(/\[(laugh|chuckle)\]/gi, "")
      .replace(/\[(sigh|pause)\]/gi, "... ")
      .replace(/\[gasp\]/gi, " — ")
      .replace(/\[(whisper|cough|throat_clear)\]/gi, "")
      .replace(/<[^>]+>/g, "")
      .replace(/\[[^\]]+\]/g, "")
      .replace(/\s+/g, " ")
      .trim();
  }

  // 5. CosyVoice 3 Engine
  if (engine.includes("cosyvoice")) {
    return text
      .replace(/\[pause\]/gi, "... ")
      .replace(/\[[^\]]+\]/g, "")
      .replace(/<[^>]+>/g, "")
      .replace(/\s+/g, " ")
      .trim();
  }

  // 6. Piper, Kokoro, MeloTTS, XTTS-v2, OmniVoice, StyleTTS2, etc.
  // Clean, crisp neural broadcast delivery: Strip all audio tags cleanly
  return text
    .replace(/\[pause\]/gi, "... ")
    .replace(/\[[^\]]+\]/g, "")
    .replace(/<[^>]+>/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

/**
 * System prompt injection guidance for LLMs to use the standard generic audio tags.
 */
export const GENERIC_AUDIO_TAGS_PROMPT_INSTRUCTION = `
🎙️ STANDARD AUDIO EMOTION TAGS:
You can naturally enhance spoken realism and pacing by tastefully inserting generic emotion tags into your dialogue when appropriate:
- [laugh] or [chuckle] : To express amusement or humor
- [sigh] : To express relief, resignation, or thoughtful weight
- [gasp] : For sudden surprise or shock
- [whisper] : For confidential or quiet remarks
- [pause] : For a dramatic or thoughtful pause

Example: "Wait, [laugh] did they really announce that? [gasp] That is huge news."
Do not overuse them; 1 or 2 per response is ideal.
`.trim();

/**
 * Automatically derives the Voice Design attribute string (for OmniVoice, Parler-TTS, CosyVoice)
 * from persona traits and parameters.
 */
export function deriveVoiceDesignInstruct(persona: {
  gender?: string;
  traits?: { age?: number };
  language?: string;
  params?: { pitchShift?: number };
}): string {
  const parts: string[] = [];

  // 1. Gender
  const gender = (persona.gender || "female").toLowerCase();
  parts.push(gender === "male" ? "male" : "female");

  // 2. Age Category
  const age = persona.traits?.age ?? 30;
  if (age < 18) parts.push("teenager");
  else if (age <= 38) parts.push("young adult");
  else if (age <= 58) parts.push("middle-aged");
  else parts.push("elderly");

  // 3. Pitch Category
  const pitch = persona.params?.pitchShift ?? 0;
  if (pitch <= -3) parts.push("very low pitch");
  else if (pitch < 0) parts.push("low pitch");
  else if (pitch >= 3) parts.push("very high pitch");
  else if (pitch > 0) parts.push("high pitch");
  else parts.push("moderate pitch");

  // 4. Accent (if English)
  if (persona.language === "en") {
    parts.push("american accent");
  }

  return parts.join(", ");
}
